{"command": "cat <<'EOF' > /tmp/repl.py
import os, pty, select, termios, time, sys, re

def strip_ansi(s):
    s = re.sub(rb'\x1b\[[0-9;?]*[A-Za-z]', b'', s)
    s = s.replace(b'\r', b'')
    return s

def run(inputs, args=(), wait=0.25, final_wait=0.6):
    pid, fd = pty.fork()
    if pid == 0:
        os.execv('/workspace/executable', ['/workspace/executable'] + list(args))
        os._exit(1)
    buf = bytearray()
    def rd(t=0.2):
        while True:
            r,_,_ = select.select([fd],[],[],t)
            if not r: return
            try: d = os.read(fd, 65536)
            except OSError: return
            if not d: return
            buf.extend(d)
    rd(0.3)
    for inp in inputs:
        os.write(fd, inp if isinstance(inp, bytes) else inp.encode())
        rd(wait)
    rd(final_wait)
    try:
        termios.tcsetattr(fd, termios.TCSANOW, termios.tcgetattr(fd))
    except Exception: pass
    try:
        os.close(fd)
    except Exception: pass
    os.waitpid(pid, os.WNOHANG)
    return bytes(buf)

if __name__ == '__main__':
    cmds = sys.argv[1:]
    outs = run([c + '\n' for c in cmds])
    print(repr(outs[-1500:]))
EOF
python3 /tmp/repl.py ':help'"}

