import os, pty, select, termios, time, sys, re, signal

def strip_ansi(s):
    s = re.sub(rb'\x1b\[[0-9;?]*[A-Za-z]', b'', s)
    s = s.replace(b'\r', b'')
    return s

def run(inputs, args=(), wait=0.25, final_wait=1.2, echo_on=True):
    pid, fd = pty.fork()
    if pid == 0:
        os.execv('/workspace/executable', ['/workspace/executable'] + list(args))
        os._exit(1)
    buf = bytearray()
    def rd(t=0.2):
        while True:
            r,_,_ = select.select([fd],[],[],t)
            if not r: return False
            try: d = os.read(fd, 65536)
            except OSError: return False
            if not d: return False
            buf.extend(d)
    rd(0.3)
    for inp in inputs:
        os.write(fd, inp if isinstance(inp, bytes) else inp.encode())
        rd(wait)
    rd(final_wait)
    try:
        os.kill(pid, signal.SIGTERM)
    except Exception: pass
    time.sleep(0.05)
    _, status = os.waitpid(pid, 0)
    try: os.close(fd)
    except Exception: pass
    if os.WIFEXITED(status): st = 'exit=%d' % os.WEXITSTATUS(status)
    else: st = 'signal=%d' % os.WTERMSIG(status)
    return bytes(buf), st
