{"command": "cat > /workspace/src/expr.py <<'PYEOF'
"""Heuristics that decide whether a snippet is a bare expression."""

import re

# Keywords that make a trailing line a statement rather than an expression.
PY_STMT = ['import', 'from', 'def', 'class', 'if', 'elif', 'else', 'for',
           'while', 'with', 'try', 'except', 'finally', 'assert', 'del',
           'global', 'nonlocal', 'pass', 'yield', 'raise', 'return', 'break',
           'continue', 'async', 'await', 'lambda']

# groovy / JVM style statement starters (prefix match, some need a space).
GROOVY_PREFIX = ['println', 'print ', 'try', 'catch', 'finally', 'if ',
                 'for ', 'while ', 'switch ', 'case ', 'return ', 'import ',
                 'package ', 'class ', 'interface ', 'enum ', 'trait ',
                 'throw ']

# Assignment operators (anything that is not a comparison).
ASSIGN_RE = re.compile(r'(?:^|[^=!<>])(?:<<|>>|//|\*\*|[+\-*/%&|^])?=(?!=)')


def _word_start(t, kw):
    if not t.startswith(kw):
        return False
    rest = t[len(kw):]
    if not rest:
        return True
    return not (rest[0].isalnum() or rest[0] == '_')


def python_expr(text):
    """True when the single line looks like a bare python expression."""
    t = text.strip()
    if not t:
        return False
    if ';' in t:
        return False
    if t.startswith('@'):
        return False
    if t.startswith('print('):
        return False
    for kw in PY_STMT:
        if _word_start(t, kw):
            return False
    if ASSIGN_RE.search(t):
        return False
    return True


def groovy_expr(text):
    """Groovy uses a slightly different (bug-compatible) rule."""
    t = text.strip()
    if not t:
        return False
    for kw in GROOVY_PREFIX:
        if t.startswith(kw):
            return False
    if ';' in t:
        if not t.endswith(';'):
            return False
        body = t[:-1]
        if not body.strip() or ';' in body:
            return False
    return True


def default_expr(text):
    return python_expr(text)
PYEOF
echo ok"}

