class Exec:
    """A single process invocation."""

    def __init__(self, argv, cwd=None, files=None, pipes=False):
        self.argv = argv
        self.cwd = cwd
        self.files = files or []
        self.pipes = pipes


class Runner:
    id = ''
    exts = []
    aliases = []
    probes = []          # list of (prog, [args])
    missing = ''         # error message when the probe binary is absent

    # ---- helpers -------------------------------------------------------
    def display(self, line):
        return expr.default_expr(line)

    def session_dir(self):
        return new_dir('run-%s-repl' % self.id)

    # ---- default implementations --------------------------------------
    def inline(self, code):
        raise NotImplementedError

    def from_file(self, path):
        raise NotImplementedError

    def session(self, lines):
        raise NotImplementedError


def indent(code, n=4):
    pad = ' ' * n
    return '\n'.join(pad + l if l.strip() else l for l in code.split('\n'))


class SimpleFileRunner(Runner):
    """Runs `<tool> [flags] <file>` where the code is written to a snippet."""

    prog = ''
    flags = ()
    ext = ''
    snippet = 'snippet.%s'
    use_abs = True
    file_cwd_parent = False
    tmp_prefix = None

    def check(self):
        pass

    def inline(self, code):
        d = new_dir(self.tmp_prefix or ('run-' + self.id))
        p = os.path.join(d, self.snippet % self.ext)
        write(p, code)
        argv = [self.prog] + list(self.flags) + [p if self.use_abs
                                                 else self.snippet % self.ext]
        return Exec(argv, cwd=d)

    def from_file(self, path):
        argv = [self.prog] + list(self.flags) + [path]
        cwd = None
        if self.file_cwd_parent:
            cwd = os.path.dirname(os.path.abspath(path)) or None
        return Exec(argv, cwd=cwd)

    def session(self, lines):
        d = self.session_dir()
        p = os.path.join(d, 'session.' + self.ext)
        write(p, self.build_session(lines))
        name = p if self.use_abs else 'session.' + self.ext
        return Exec([self.prog] + list(self.flags) + [name], cwd=d)

    def build_session(self, lines):
        out = self.prelude()
        for l in lines:
            t = l.strip()
            if not t:
                continue
            out += self.emit(t)
        return out

    def prelude(self):
        return ''

    def emit(self, t):
        return t + '\n'


