class CFamily(Runner):
    """Shared logic for C and C++."""

    id = ''
    exts = []
    compilers = []
    std = ''
    out_name = ''
    file_name = 'main.c'
    tmp_prefix = 'run-c'

    def display(self, line):
        return expr.default_expr(line)

    def session_dir(self):
        return new_dir(self.repl_prefix)

    def _wrap_inline(self, code):
        if re.search(r'\bmain\s*\(', code):
            return code
        return self.inline_head() + indent(code) + self.inline_tail()

    def inline_head(self):
        return '#include <stdio.h>\n\nint main(void)\n{\n'

    def inline_tail(self):
        return '\n    return 0;\n}\n'

    def inline(self, code):
        d = new_dir(self.tmp_prefix)
        p = os.path.join(d, self.file_name)
        write(p, self._wrap_inline(code))
        return Exec([self.compiler(), p, '-std=' + self.std, '-O0', '-Wall',
                     '-Wextra', '-o', os.path.join(d, self.out_name)])

    def run_stage(self, d):
        return Exec([os.path.join(d, self.out_name)])

    def from_file(self, path):
        d = new_dir(self.tmp_prefix)
        p = os.path.join(d, self.file_name)
        shutil.copyfile(path, p)
        return Exec([self.compiler(), p, '-std=' + self.std, '-O0', '-Wall',
                     '-Wextra', '-o', os.path.join(d, self.out_name)])

    def compiler(self):
        return self.compilers[0]

    def session(self, lines):
        raise NotImplementedError


