"""Heuristic language detection."""

import os
import re

import languages


def compile_patterns():
    anchored = {}
    for lid, pats in languages.PATTERNS.items():
        anchored[lid] = [re.compile(p, re.M) for p in pats]
    unanchored = {}
    for lid, pats in languages.UNANCHORED.items():
        unanchored[lid] = [re.compile(p) for p in pats]
    return anchored, unanchored


ANCHORED, UNANCHORED = compile_patterns()

SHEBANG_RE = re.compile(languages.SHEBANG + r'([A-Za-z0-9_.+-]+)')


def detect(code):
    """Return the detected language id (python is the fallback)."""
    for lid in languages.DETECT_ORDER:
        pats = ANCHORED.get(lid, [])
        for pat in pats:
            if pat.search(code):
                return lid
        for pat in UNANCHORED.get(lid, []):
            if pat.search(code):
                return lid
    m = SHEBANG_RE.search(code)
    if m:
        name = m.group(1)
        for key, lid in languages.SHEBANG_LANGS.items():
            if name.startswith(key):
                return lid
    return 'python'
