"""Process execution helpers."""

import os
import subprocess
import sys
import time

import runners


class RunError(Exception):
    """A fatal error; the message is printed as `Error: ...`."""

    def __init__(self, message, cause=None):
        super().__init__(message)
        self.message = message
        self.cause = cause

    def render(self):
        out = 'Error: %s\n' % self.message
        if self.cause:
            out += '\nCaused by:\n    %s\n' % self.cause
        return out


def spawn(prog_args, cwd=None, capture=True, pipes=False):
    """Run a subprocess, capturing stdout/stderr unless pipes is set."""
    argv = prog_args
    if not capture or pipes:
        p = subprocess.Popen(argv, cwd=cwd)
        t0 = time.time()
        rc = p.wait()
        return rc, int((time.time() - t0) * 1000), '', ''
    try:
        p = subprocess.run(argv, cwd=cwd, capture_output=True)
    except FileNotFoundError as e:
        raise runners.MissingBinary(str(e))
    return (p.returncode,
            int((time.time() - p._start) * 1000) if hasattr(p, '_start') else 0,
            p.stdout.decode('utf-8', 'replace'),
            p.stderr.decode('utf-8', 'replace'))
PYEOF
echo ok"}

