"""Entry point for the `run` universal multi-language runner."""

import os
import re
import subprocess
import sys
import time

import cli
import detect
import expr
import languages
import runners
import repl


def eprint(msg):
    sys.stderr.write(msg)


def resolve_lang(text):
    """Resolve a language name or alias (case insensitive, trimmed)."""
    t = text.strip().lower()
    if not t:
        return None
    if t in runners.RUNNERS:
        return runners.RUNNERS[t]
    for lid, lang in runners.RUNNERS.items():
        for al in lang.aliases:
            if al.lower() == t:
                return lang
    return None


def lang_for_ext(path):
    base = os.path.basename(path)
    if '.' not in base:
        return None
    ext = base.rsplit('.', 1)[1]
    for lid, lang in runners.RUNNERS.items():
        for e in lang.exts:
            if e == ext:
                return lang
    return None


def available():
    return ', '.join(languages.LANG_IDS)


def check_availability(lang, mode='inline'):
    """Ensure the interpreter exists, raising RunError otherwise."""
    if isinstance(lang, runners.Java):
        for prog, args in lang.probes:
            try:
                subprocess.run([prog] + args, capture_output=True)
            except FileNotFoundError:
                raise runners.RunError(lang.missing)
        return
    if isinstance(lang, runners.Typescript):
        try:
            subprocess.run(['deno', '--version'], capture_output=True)
        except FileNotFoundError:
            where = {'inline': 'inline', 'file': 'file'}.get(mode, mode)
            raise runners.RunError(
                "failed to run Deno for %s execution because 'deno' was not "
                "found in PATH. Install Deno from "
                "https://deno.land/manual/getting_started/installation or "
                "ensure the binary is available on your PATH" % where)
        return
    if isinstance(lang, runners.C):
        for prog in ('cc', 'gcc'):
            try:
                subprocess.run([prog, '--version'], capture_output=True)
                lang._cc = prog
                return
            except FileNotFoundError:
                continue
        raise runners.RunError(
            'C support requires the `cc` executable. Install a C compiler '
            'and ensure it is on your PATH.')
    if isinstance(lang, runners.Cpp):
        for prog in ('c++', 'g++'):
            try:
                subprocess.run([prog, '--version'], capture_output=True)
                lang._cc = prog
                return
            except FileNotFoundError:
                continue
        raise runners.RunError(
            'C++ support requires the `c++` executable. Install a C++ '
            'compiler and ensure it is on your PATH.')
    if isinstance(lang, runners.CSharp):
